async function getSupabaseClient() {
  if (supabaseClient) return supabaseClient;
  if (!window.supabase) await new Promise((resolve, reject) => { const script = document.createElement('script'); script.src = 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2'; script.onload = resolve; script.onerror = reject; document.head.appendChild(script); });
  supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY);
  return supabaseClient;
}
function workspaceSnapshot() { return Object.fromEntries(syncedStorageKeys.map((key) => [key, localStorage.getItem(key)])); }
function queueWorkspaceSync() { clearTimeout(workspaceSyncTimer); workspaceSyncTimer = setTimeout(async () => { try { const client = await getSupabaseClient(); const { data: { user } } = await client.auth.getUser(); if (!user) return; await client.from('user_workspaces').upsert({ user_id: user.id, data: workspaceSnapshot(), updated_at: new Date().toISOString() }); } catch (error) { /* Offline or unconfigured database: browser data stays safe locally. */ } }, 700); }
function enableWorkspaceSync() { const originalSetItem = localStorage.setItem.bind(localStorage); localStorage.setItem = (key, value) => { originalSetItem(key, value); if (syncedStorageKeys.includes(key)) queueWorkspaceSync(); }; }
async function restoreWorkspace() { try { const client = await getSupabaseClient(); const { data: { user } } = await client.auth.getUser(); if (!user) return; const { data, error } = await client.from('user_workspaces').select('data').eq('user_id', user.id).maybeSingle(); if (error) return; if (data?.data && Object.values(data.data).some((value) => value)) { const changed = Object.entries(data.data).some(([key, value]) => syncedStorageKeys.includes(key) && value !== null && localStorage.getItem(key) !== value); if (changed) { Object.entries(data.data).forEach(([key, value]) => { if (syncedStorageKeys.includes(key) && value !== null) localStorage.setItem(key, value); }); location.reload(); } } else queueWorkspaceSync(); } catch (error) { /* The setup SQL may not have been run yet. */ } }
async function restoreSignedInAccount() { if (location.pathname.endsWith('account.html')) return; try { const client = await getSupabaseClient(); const { data: { user } } = await client.auth.getUser(); if (!user) return; const account = JSON.parse(localStorage.getItem('revisie-account') || 'null'); if (!account || account.id !== user.id) { localStorage.setItem('revisie-account', JSON.stringify({ id: user.id, name: user.user_metadata?.display_name || user.email.split('@')[0], email: user.email })); location.reload(); return; } await restoreWorkspace(); } catch (error) { /* Sign-in remains available even if offline. */ } }
