function notify(message) { if (!toast) return; toast.textContent = message; toast.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), 2800); }
function normalizeSidebar() { const sidebar = document.querySelector('.sidebar'); if (!sidebar) return; sidebar.innerHTML = `<a class="brand brand-logo" href="index.html" aria-label="REVISIÉ home"><img src="assets/revisie-logo.png?v=2" alt="REVISIÉ" width="148" height="63"></a><div class="workspace-switcher"><div class="avatar small">SH</div><div><strong>Sean's workspace</strong><small>GCSE Higher Tier</small></div>${icon('chevrons-up-down')}</div><nav class="main-nav" aria-label="Main navigation"><p class="nav-label">Workspace</p><a class="nav-item" data-page="index.html" href="index.html">${icon('layout-dashboard')}Overview</a><a class="nav-item" data-page="subjects.html" href="subjects.html">${icon('library')}Subjects<span class="nav-count">10</span></a><a class="nav-item" data-page="flashcards.html" href="flashcards.html">${icon('layers-3')}Flashcards<span class="nav-count alert">18</span></a><a class="nav-item" data-page="notes.html" href="notes.html">${icon('notebook-pen')}Notes</a><a class="nav-item" data-page="resources.html" href="resources.html">${icon('folder-open')}Resources</a><p class="nav-label second">Tools</p><a class="nav-item" data-page="planner.html" href="planner.html">${icon('calendar-days')}Revision planner</a><a class="nav-item" data-page="progress.html" href="progress.html">${icon('chart-no-axes-combined')}Progress</a></nav><div class="sidebar-bottom"><div class="account-panel"><div class="account-panel-icon">${icon('user-round')}</div><div><strong>Personal workspace</strong><small>GCSE Higher Tier</small></div></div><a class="nav-item muted" href="settings.html">${icon('settings-2')}Settings</a><a class="nav-item muted" href="help.html">${icon('circle-help')}Help centre</a></div>`; }
function subjectCount() { return Object.keys(subjectData).length + customSubjects.filter((subject) => !subjectData[subject.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')]).length; }
function remainingFlashcardCount() { const saved = topicProgress(); return Object.keys(subjectData).reduce((total, subjectKey) => total + getUnits(subjectKey).reduce((unitTotal, unit) => unitTotal + Math.max(0, getDeck(subjectKey, unit.name).length - Number(saved[topicProgressKey(subjectKey, unit.name)] || 0)), 0), 0); }
function updateNavigationCounts() { const subjects = document.querySelector('[data-page="subjects.html"] .nav-count'); const flashcards = document.querySelector('[data-page="flashcards.html"] .nav-count'); const totalSubjects = subjectCount(); const remainingCards = remainingFlashcardCount(); if (subjects) { subjects.textContent = totalSubjects; subjects.title = `${totalSubjects} subjects`; } if (flashcards) { flashcards.textContent = remainingCards; flashcards.title = `${remainingCards} flashcards remaining`; } }
function normalizeTopbar() { const topbar = document.querySelector('.topbar'); if (!topbar) return; const avatar = topbar.querySelector('.avatar'); let actions = topbar.querySelector('.top-actions'); if (!actions && avatar) { actions = document.createElement('div'); actions.className = 'top-actions'; topbar.appendChild(actions); actions.appendChild(avatar); } if (actions && !actions.querySelector('#siteSearch')) actions.insertAdjacentHTML('afterbegin', `<button class="icon-button" id="siteSearch" type="button" title="Search" aria-label="Search subjects and topics">${icon('search')}</button>`); if (actions && !actions.querySelector('#mobileMenu')) actions.insertAdjacentHTML('afterbegin', `<button class="icon-button mobile-menu-button" id="mobileMenu" type="button" aria-label="Open navigation menu" aria-expanded="false">${icon('menu')}</button>`); }
function normalizeUtilityLinks() { document.querySelectorAll('.nav-item.muted').forEach((item) => { if (item.textContent.trim() === 'Settings') { item.href = 'settings.html'; item.dataset.page = 'settings.html'; } if (item.textContent.trim() === 'Help centre') { item.href = 'help.html'; item.dataset.page = 'help.html'; } }); }
function activateNav() { const path = location.pathname.split('/').pop() || 'index.html'; document.querySelectorAll('.nav-item[data-page]').forEach((item) => item.classList.toggle('active', item.dataset.page === path)); }
function cleanRemovedAssistant() { document.querySelectorAll('a[href="assistant.html"], [data-page="assistant.html"]').forEach((item) => item.remove()); document.querySelectorAll('.help-card').forEach((card) => { if (card.querySelector('h2')?.textContent.trim() === 'Study assistant') { card.querySelector('h2').textContent = 'Study methods'; card.querySelector('p').textContent = 'Use active recall, spaced practice, and short written summaries to turn each unit into knowledge you can retrieve under exam pressure.'; card.querySelector('.help-icon').innerHTML = icon('brain'); } }); }
function openModal(title, body) { closeModal(); const backdrop = document.createElement('div'); backdrop.className = 'modal-backdrop open'; backdrop.innerHTML = `<section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><header class="modal-header"><h2>${title}</h2><button class="modal-close" aria-label="Close">${icon('x')}</button></header><div class="modal-body">${body}</div></section>`; document.body.appendChild(backdrop); lucide.createIcons(); backdrop.addEventListener('click', (event) => { if (event.target === backdrop || event.target.closest('.modal-close')) closeModal(); }); return backdrop; }
function closeModal() { document.querySelector('.modal-backdrop')?.remove(); }
function escapeHtml(value) { return String(value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]); }
function subjectRoute(subjectKey) { const subject = subjectData[subjectKey]; return ['mathematics', 'biology', 'history', 'psychology'].includes(subjectKey) ? `${subjectKey}.html` : `subject.html?name=${encodeURIComponent(subject?.label || subjectKey)}`; }
function openSiteSearch() {
  const entries = Object.entries(subjectData).flatMap(([key, subject]) => [{ key, type: 'Subject', title: subject.label, detail: subject.topic }].concat(getUnits(key).flatMap((unit) => [{ key, type: 'Topic', title: unit.name, detail: subject.label }, ...getDeck(key, unit.name).map(([question]) => ({ key, type: 'Flashcard', title: question, detail: `${subject.label} · ${unit.name}` }))])));
  const backdrop = openModal('Search', `<form class="notes-form" id="siteSearchForm"><input id="siteSearchInput" class="note-title" type="search" autocomplete="off" placeholder="Search subjects, topics, or flashcards"><div id="siteSearchResults" class="search-results" aria-live="polite"></div></form>`);
  const input = backdrop.querySelector('#siteSearchInput'); const results = backdrop.querySelector('#siteSearchResults');
  const render = () => { const query = normaliseQuestion(input.value); if (!query) { results.innerHTML = '<p class="empty-state">Search your subjects, topics, or flashcard questions.</p>'; return; } const matches = entries.filter((entry) => normaliseQuestion(`${entry.title} ${entry.detail}`).includes(query)).slice(0, 12); results.innerHTML = matches.length ? matches.map((entry) => `<button type="button" class="search-result" data-search-subject="${escapeHtml(entry.key)}"><span>${escapeHtml(entry.type)}</span><strong>${escapeHtml(entry.title)}</strong><small>${escapeHtml(entry.detail)}</small></button>`).join('') : '<p class="empty-state">No matching subjects, topics, or flashcards.</p>'; results.querySelectorAll('[data-search-subject]').forEach((button) => button.addEventListener('click', () => { location.href = subjectRoute(button.dataset.searchSubject); })); };
  input.addEventListener('input', render); backdrop.querySelector('#siteSearchForm').addEventListener('submit', (event) => event.preventDefault()); render(); input.focus();
}
function setupTopbarActions() { const search = document.getElementById('siteSearch'); if (search) search.addEventListener('click', openSiteSearch); const menu = document.getElementById('mobileMenu'); if (menu) { let backdrop = document.querySelector('.mobile-nav-backdrop'); if (!backdrop) { backdrop = document.createElement('button'); backdrop.className = 'mobile-nav-backdrop'; backdrop.type = 'button'; backdrop.setAttribute('aria-label', 'Close navigation menu'); document.body.appendChild(backdrop); } const closeMenu = () => { document.body.classList.remove('mobile-menu-open'); menu.setAttribute('aria-expanded', 'false'); menu.setAttribute('aria-label', 'Open navigation menu'); }; menu.addEventListener('click', () => { const isOpen = document.body.classList.toggle('mobile-menu-open'); menu.setAttribute('aria-expanded', String(isOpen)); menu.setAttribute('aria-label', isOpen ? 'Close navigation menu' : 'Open navigation menu'); }); backdrop.addEventListener('click', closeMenu); document.querySelectorAll('.sidebar a').forEach((link) => link.addEventListener('click', closeMenu)); } const avatar = document.querySelector('.topbar .avatar'); if (avatar) { avatar.setAttribute('role', 'button'); avatar.setAttribute('tabindex', '0'); avatar.setAttribute('aria-label', 'Open account'); avatar.addEventListener('click', () => { location.href = 'account.html'; }); avatar.addEventListener('keydown', (event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); location.href = 'account.html'; } }); } }
function reviewCards(cards, title) { let index = 0; const render = () => { const card = cards[index]; const backdrop = openModal(title, `<div class="flashcard-meta"><span>Card ${index + 1} of ${cards.length}</span><span>Click to reveal</span></div><button class="flashcard" id="flashcard"><div><p>${card[0]}</p><small>Question</small></div></button><div class="review-actions"><button class="again" id="again">Review again</button><button class="known" id="known">I knew this</button></div>`); const flashcard = backdrop.querySelector('#flashcard'); flashcard.addEventListener('click', () => { const answer = flashcard.classList.toggle('answer'); flashcard.querySelector('p').textContent = answer ? card[1] : card[0]; flashcard.querySelector('small').textContent = answer ? 'Answer' : 'Question'; }); backdrop.querySelector('#again').addEventListener('click', () => { markStudyComplete(); notify('Card moved to the end of your queue.'); index = (index + 1) % cards.length; render(); }); backdrop.querySelector('#known').addEventListener('click', () => { markStudyComplete(); notify('Card marked as known. Nice work.'); index = (index + 1) % cards.length; render(); }); }; render(); }
function addFlashcard() { const subjectOptions = Object.entries(subjectData).filter(([key]) => key !== 'psychology').map(([key, subject]) => `<option value="${key}">${subject.label}</option>`).join(''); const backdrop = openModal('Make a flashcard', `<form class="notes-form"><label class="upload-label" for="cardSubject">Subject</label><select id="cardSubject" class="note-subject">${subjectOptions}</select><label class="upload-label" for="cardUnit">Unit / topic</label><select id="cardUnit" class="note-subject"></select><input id="cardQuestion" class="note-title" required placeholder="Question or prompt"><textarea id="cardAnswer" required placeholder="Answer"></textarea><button class="primary-button" type="submit">Save flashcard ${icon('plus')}</button></form>`); const subjectSelect = backdrop.querySelector('#cardSubject'); const unitSelect = backdrop.querySelector('#cardUnit'); const updateUnits = () => { unitSelect.innerHTML = getUnits(subjectSelect.value).map((unit) => `<option>${unit.name}</option>`).join(''); }; subjectSelect.addEventListener('change', updateUnits); updateUnits(); backdrop.querySelector('form').addEventListener('submit', (event) => { event.preventDefault(); const question = backdrop.querySelector('#cardQuestion').value.trim(); if (getDeck(subjectSelect.value, unitSelect.value).some((card) => normaliseQuestion(card[0]) === normaliseQuestion(question))) { notify('That question is already in this deck.'); return; } userCards.push({ subject: subjectSelect.value, unit: unitSelect.value, question, answer: backdrop.querySelector('#cardAnswer').value.trim() }); localStorage.setItem('revisie-flashcards', JSON.stringify(userCards)); closeModal(); notify('Flashcard saved to your subject deck.'); }); }
function addFlashcardFor(subjectKey, unitName) { const subject = subjectData[subjectKey]; const backdrop = openModal(`New ${subject.label} flashcard`, `<form class="notes-form"><label class="upload-label">Unit / topic</label><select id="cardUnit" class="note-subject">${getUnits(subjectKey).map((unit) => `<option ${unit.name === unitName ? 'selected' : ''}>${unit.name}</option>`).join('')}</select><input id="cardQuestion" class="note-title" required placeholder="Question or prompt"><textarea id="cardAnswer" required placeholder="Answer"></textarea><button class="primary-button" type="submit">Save flashcard ${icon('plus')}</button></form>`); backdrop.querySelector('form').addEventListener('submit', (event) => { event.preventDefault(); const unit = backdrop.querySelector('#cardUnit').value; const question = backdrop.querySelector('#cardQuestion').value.trim(); if (getDeck(subjectKey, unit).some((card) => normaliseQuestion(card[0]) === normaliseQuestion(question))) { notify('That question is already in this deck.'); return; } userCards.push({ subject: subjectKey, unit, question, answer: backdrop.querySelector('#cardAnswer').value.trim() }); localStorage.setItem('revisie-flashcards', JSON.stringify(userCards)); closeModal(); notify('Flashcard saved to this subject.'); }); }
function openCardManager(subjectKey, unitName) {
  const subject = subjectData[subjectKey];
  const starterCards = getStarterDeck(subjectKey, unitName).map((card, index) => ({ card, index }));
  const personalCards = userCards.map((card, index) => ({ ...card, index })).filter((card) => card.subject === subjectKey && card.unit === unitName);
  const starterList = starterCards.map(({ card, index }) => `<div class="managed-card"><div><strong>${card[0]}</strong><small>${card[1]}</small></div><div><button data-edit-starter="${index}" aria-label="Edit flashcard">${icon('pencil')}</button></div></div>`).join('');
  const personalList = personalCards.map((card) => `<div class="managed-card"><div><strong>${card.question}</strong><small>${card.answer}</small></div><div><button data-edit-card="${card.index}" aria-label="Edit flashcard">${icon('pencil')}</button><button data-delete-card="${card.index}" aria-label="Delete flashcard">${icon('trash-2')}</button></div></div>`).join('') || '<p class="empty-state">No personal cards in this topic yet.</p>';
  const options = getUnits(subjectKey).map((unit) => `<option ${unit.name === unitName ? 'selected' : ''}>${unit.name}</option>`).join('');
  const backdrop = openModal(`${subject.label} flashcards`, `<label class="upload-label" for="manageUnit">Topic</label><select id="manageUnit" class="note-subject">${options}</select><div class="managed-card-intro">Starter questions — edit any question or answer to personalise it.</div><div class="managed-cards">${starterList}</div><div class="managed-card-intro">Your flashcards</div><div class="managed-cards">${personalList}</div><button class="primary-button" id="addManagedCard">Add flashcard ${icon('plus')}</button>`);
  backdrop.querySelector('#manageUnit').addEventListener('change', (event) => openCardManager(subjectKey, event.target.value));
  backdrop.querySelector('#addManagedCard').addEventListener('click', () => addFlashcardFor(subjectKey, unitName));
  backdrop.querySelectorAll('[data-edit-starter]').forEach((button) => button.addEventListener('click', () => editStarterFlashcard(subjectKey, unitName, Number(button.dataset.editStarter))));
  backdrop.querySelectorAll('[data-edit-card]').forEach((button) => button.addEventListener('click', () => editFlashcard(Number(button.dataset.editCard), subjectKey, unitName)));
  backdrop.querySelectorAll('[data-delete-card]').forEach((button) => button.addEventListener('click', () => { const index = Number(button.dataset.deleteCard); if (confirm('Delete this flashcard?')) { userCards.splice(index, 1); localStorage.setItem('revisie-flashcards', JSON.stringify(userCards)); openCardManager(subjectKey, unitName); notify('Flashcard deleted.'); } }));
}
function editStarterFlashcard(subjectKey, unitName, index) {
  const card = getStarterDeck(subjectKey, unitName)[index]; if (!card) return;
  const backdrop = openModal('Edit starter flashcard', `<form class="notes-form"><input id="cardQuestion" class="note-title" required value="${card[0]}"><textarea id="cardAnswer" required>${card[1]}</textarea><button class="primary-button" type="submit">Save changes ${icon('check')}</button></form>`);
  backdrop.querySelector('form').addEventListener('submit', (event) => { event.preventDefault(); starterCardOverrides[starterCardKey(subjectKey, unitName, index)] = { question: backdrop.querySelector('#cardQuestion').value.trim(), answer: backdrop.querySelector('#cardAnswer').value.trim() }; localStorage.setItem('revisie-starter-card-overrides', JSON.stringify(starterCardOverrides)); openCardManager(subjectKey, unitName); notify('Starter flashcard updated.'); });
}
function editFlashcard(index, subjectKey, unitName) { const card = userCards[index]; if (!card) return; const backdrop = openModal('Edit flashcard', `<form class="notes-form"><input id="cardQuestion" class="note-title" required value="${card.question}"><textarea id="cardAnswer" required>${card.answer}</textarea><button class="primary-button" type="submit">Save changes ${icon('check')}</button></form>`); backdrop.querySelector('form').addEventListener('submit', (event) => { event.preventDefault(); card.question = backdrop.querySelector('#cardQuestion').value.trim(); card.answer = backdrop.querySelector('#cardAnswer').value.trim(); localStorage.setItem('revisie-flashcards', JSON.stringify(userCards)); openCardManager(subjectKey, unitName); notify('Flashcard updated.'); }); }
function openNotes(subjectKey = currentSubject, noteId = null) {
  const existing = noteLibrary.find((note) => note.id === noteId) || noteLibrary.find((note) => note.subject === subjectKey);
  const subjectOptions = Object.entries(subjectData).map(([key, subject]) => `<option value="${key}" ${key === subjectKey ? 'selected' : ''}>${subject.label}</option>`).join('');
  const backdrop = openModal(existing ? 'Edit note' : 'New note', `<form class="notes-form"><input id="noteTitle" class="note-title" required placeholder="Note title" value="${existing?.title || ''}"><select id="noteSubject" class="note-subject">${subjectOptions}${customSubjects.map((subject) => `<option value="${subject.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}">${subject.name}</option>`).join('')}</select><textarea id="notesText" placeholder="Capture an idea, summary, or question...">${existing?.body || localStorage.getItem('revisie-notes') || ''}</textarea><label class="upload-label" for="noteImage">Add a photo of handwritten notes</label><input id="noteImage" type="file" accept="image/*" capture="environment"><img id="notePreview" class="note-preview" alt="Uploaded note preview" ${existing?.image ? `src="${existing.image}"` : 'hidden'}><button class="ocr-button" type="button" id="ocrButton">Extract text from photo</button><button class="primary-button" type="submit">Save note ${icon('check')}</button></form>`);
  const image = backdrop.querySelector('#noteImage'); const preview = backdrop.querySelector('#notePreview'); let photoData = existing?.image || ''; let photoReady = Promise.resolve();
  image.addEventListener('change', () => { const file = image.files[0]; if (!file) return; preview.src = URL.createObjectURL(file); preview.hidden = false; photoReady = imageToDataUrl(file).then((data) => { photoData = data; }).catch(() => { photoData = ''; notify('Photo could not be saved. Try a smaller image.'); }); });
  backdrop.querySelector('#ocrButton').addEventListener('click', () => runOcr(backdrop));
  backdrop.querySelector('form').addEventListener('submit', async (event) => { event.preventDefault(); await photoReady; const note = { id: existing?.id || Date.now(), title: backdrop.querySelector('#noteTitle').value.trim(), subject: backdrop.querySelector('#noteSubject').value, body: backdrop.querySelector('#notesText').value.trim(), image: photoData, updatedAt: new Date().toISOString() }; const index = noteLibrary.findIndex((item) => item.id === note.id); if (index >= 0) noteLibrary[index] = note; else noteLibrary.unshift(note); try { localStorage.setItem('revisie-note-library', JSON.stringify(noteLibrary)); } catch (error) { notify('This photo is too large to save. Try a smaller one.'); return; } localStorage.setItem('revisie-notes', note.body); closeModal(); renderNoteSurfaces(); notify('Note saved to your library.'); });
}
function preprocessImage(file) { return new Promise((resolve, reject) => { const image = new Image(); image.onload = () => { const canvas = document.createElement('canvas'); const scale = Math.min(1, 1800 / image.width); canvas.width = image.width * scale; canvas.height = image.height * scale; const context = canvas.getContext('2d'); context.filter = 'grayscale(1) contrast(1.35) brightness(1.08)'; context.drawImage(image, 0, 0, canvas.width, canvas.height); canvas.toBlob(resolve, 'image/jpeg', .92); }; image.onerror = reject; image.src = URL.createObjectURL(file); }); }
function imageToDataUrl(file) { return new Promise((resolve, reject) => { const image = new Image(); const objectUrl = URL.createObjectURL(file); image.onload = () => { const scale = Math.min(1, 1200 / Math.max(image.width, image.height)); const canvas = document.createElement('canvas'); canvas.width = Math.round(image.width * scale); canvas.height = Math.round(image.height * scale); canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height); URL.revokeObjectURL(objectUrl); resolve(canvas.toDataURL('image/jpeg', .8)); }; image.onerror = () => { URL.revokeObjectURL(objectUrl); reject(new Error('Image could not be read.')); }; image.src = objectUrl; }); }
function openPhotoZoom(source, alt = 'Attached note photo') { const backdrop = openModal('Photo', `<img class="photo-zoom" src="${source}" alt="${alt}">`); backdrop.querySelector('.photo-zoom').addEventListener('click', () => closeModal()); }
function viewNote(noteId) { const note = noteLibrary.find((item) => item.id === noteId); if (!note) return; const body = escapeHtml(note.body || '').replace(/\n/g, '<br>'); const backdrop = openModal(note.title, `<div class="flashcard-meta"><span>${subjectData[note.subject]?.label || note.subject}</span><span>${new Date(note.updatedAt).toLocaleDateString()}</span></div><div class="note-view">${body || '<em>No written content.</em>'}</div>${note.image ? `<img class="note-view-image" src="${note.image}" alt="Photo attached to ${note.title}" title="Click to zoom">` : ''}<button class="primary-button" id="editViewedNote">Edit note ${icon('pencil')}</button>`); backdrop.querySelector('#editViewedNote').addEventListener('click', () => openNotes(note.subject, note.id)); backdrop.querySelector('.note-view-image')?.addEventListener('click', () => openPhotoZoom(note.image, `Photo attached to ${note.title}`)); }
function fileToDataUrl(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(new Error('File could not be read.')); reader.readAsDataURL(file); }); }
function renderResources() { const list = document.querySelector('.resource-list'); if (!list) return; list.innerHTML = resourceLibrary.length ? resourceLibrary.map((resource) => `<article class="resource-row">${icon('file-text')}<div><strong>${escapeHtml(resource.name)}</strong><small>${Math.ceil(resource.size / 1024)} KB · saved ${new Date(resource.savedAt).toLocaleDateString()}</small></div><button data-open-resource="${resource.id}">Open</button><button data-delete-resource="${resource.id}">Delete</button></article>`).join('') : '<p class="empty-state">Save PDFs here so they are ready when you revise.</p>'; list.querySelectorAll('[data-open-resource]').forEach((button) => button.addEventListener('click', () => { const resource = resourceLibrary.find((item) => item.id === Number(button.dataset.openResource)); if (resource) openModal(resource.name, `<iframe class="resource-frame" src="${resource.data}" title="${escapeHtml(resource.name)}"></iframe>`); })); list.querySelectorAll('[data-delete-resource]').forEach((button) => button.addEventListener('click', () => { const index = resourceLibrary.findIndex((item) => item.id === Number(button.dataset.deleteResource)); if (index >= 0 && confirm('Delete this PDF?')) { resourceLibrary.splice(index, 1); localStorage.setItem('revisie-resources', JSON.stringify(resourceLibrary)); renderResources(); notify('PDF deleted.'); } })); }
function setupResourcesPage() { if (!location.pathname.endsWith('resources.html')) return; const form = document.getElementById('resourceUploadForm'); if (!form) return; form.addEventListener('submit', async (event) => { event.preventDefault(); const file = document.getElementById('resourceFile').files[0]; if (!file) { notify('Choose a PDF first.'); return; } if (file.type !== 'application/pdf') { notify('Please choose a PDF file.'); return; } if (file.size > 3 * 1024 * 1024) { notify('Please choose a PDF smaller than 3 MB.'); return; } const button = form.querySelector('button'); button.disabled = true; button.textContent = 'Saving PDF…'; try { const resource = { id: Date.now(), name: file.name, size: file.size, data: await fileToDataUrl(file), savedAt: new Date().toISOString() }; const saved = [...resourceLibrary, resource]; localStorage.setItem('revisie-resources', JSON.stringify(saved)); resourceLibrary.push(resource); form.reset(); renderResources(); notify('PDF saved to Resources.'); } catch (error) { notify('This PDF could not be saved. Try a smaller file.'); } finally { button.disabled = false; button.textContent = 'Save PDF'; } }); renderResources(); }
async function runOcr(backdrop) { const file = backdrop.querySelector('#noteImage').files[0]; if (!file) { notify('Choose a photo first.'); return; } const button = backdrop.querySelector('#ocrButton'); button.textContent = 'Reading photo...'; if (!window.Tesseract) { await new Promise((resolve, reject) => { const script = document.createElement('script'); script.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js'; script.onload = resolve; script.onerror = reject; document.head.appendChild(script); }); } try { const processedImage = await preprocessImage(file); const result = await Tesseract.recognize(processedImage, 'eng'); const text = result.data.text.trim(); backdrop.querySelector('#notesText').value = text || 'No text detected. Try a brighter, flatter photo.'; button.textContent = text ? 'Text extracted' : 'Try another photo'; } catch (error) { button.textContent = 'OCR unavailable'; notify('OCR could not read that image. You can still type your note.'); } }
function renderNoteSurfaces() { const noteArea = document.querySelector('.notes-library'); if (noteArea) { noteArea.innerHTML = noteLibrary.length ? noteLibrary.map((note) => `<article class="saved-note"><button class="saved-note-open" data-open-note="${note.id}" aria-label="Open ${note.title}"><div><span class="subject-label">${subjectData[note.subject]?.label || note.subject}</span><h3>${note.title}</h3><p>${note.body.slice(0, 140)}${note.body.length > 140 ? '...' : ''}</p></div>${note.image ? `<img class="saved-note-image" src="${note.image}" alt="Photo attached to ${note.title}">` : ''}</button><div class="saved-note-actions"><button data-edit-note="${note.id}" aria-label="Edit ${note.title}">${icon('pencil')}</button><button data-delete-note="${note.id}" aria-label="Delete ${note.title}">${icon('trash-2')}</button></div></article>`).join('') : '<p class="empty-state">Your saved notes will appear here.</p>'; noteArea.querySelectorAll('[data-open-note]').forEach((button) => button.addEventListener('click', () => viewNote(Number(button.dataset.openNote)))); noteArea.querySelectorAll('[data-edit-note]').forEach((button) => button.addEventListener('click', () => openNotes(currentSubject, Number(button.dataset.editNote)))); noteArea.querySelectorAll('[data-delete-note]').forEach((button) => button.addEventListener('click', () => { const index = noteLibrary.findIndex((note) => note.id === Number(button.dataset.deleteNote)); if (index >= 0 && confirm('Delete this note?')) { noteLibrary.splice(index, 1); localStorage.setItem('revisie-note-library', JSON.stringify(noteLibrary)); renderNoteSurfaces(); notify('Note deleted.'); } })); } const subjectNotes = document.querySelector('.subject-notes'); if (subjectNotes) { const notes = noteLibrary.filter((note) => note.subject === currentSubject); subjectNotes.innerHTML = notes.length ? notes.map((note) => `<button class="subject-note" data-open-note="${note.id}"><strong>${note.title}</strong><small>${note.body.slice(0, 90)}${note.body.length > 90 ? '...' : ''}</small>${note.image ? '<small>Photo attached</small>' : ''}</button>`).join('') : '<p class="empty-state">No notes for this subject yet.</p>'; subjectNotes.querySelectorAll('[data-open-note]').forEach((button) => button.addEventListener('click', () => viewNote(Number(button.dataset.openNote)))); } }
function setupNotesPage() { if (!location.pathname.endsWith('notes.html')) return; const wrap = document.querySelector('.page-wrap'); if (!wrap || document.querySelector('.notes-library')) return; wrap.insertAdjacentHTML('beforeend', '<section class="notes-section"><div class="section-heading"><div><p class="eyebrow">SAVED KNOWLEDGE</p><h2>All notes</h2></div></div><div class="notes-library"></div></section>'); renderNoteSurfaces(); }
function plannerItems() { return JSON.parse(localStorage.getItem('revisie-planner-items') || '[]'); }
function openPlanner() { const items = plannerItems(); const list = items.length ? items.map((item) => `<div class="planner-row ${item.done ? 'complete' : ''}"><input data-plan-done="${item.id}" type="checkbox" ${item.done ? 'checked' : ''}><label><strong>${item.title}</strong><small>${item.subject} · ${item.date || 'Today'} · ${item.minutes} min</small></label><button data-edit-plan="${item.id}" aria-label="Edit ${item.title}">${icon('pencil')}</button><button data-delete-plan="${item.id}" aria-label="Delete ${item.title}">${icon('trash-2')}</button></div>`).join('') : '<p class="empty-state">Your plan is empty. Add a session to decide what happens next.</p>'; const backdrop = openModal('Organise your revision', `<p class="hero-copy">Build a plan that fits your day. Sessions are saved in this browser.</p><div class="planner-list">${list}</div><button class="primary-button" id="addPlan">Add study session ${icon('plus')}</button>`); backdrop.querySelector('#addPlan').addEventListener('click', () => editPlan()); backdrop.querySelectorAll('[data-plan-done]').forEach((input) => input.addEventListener('change', () => { const item = items.find((entry) => entry.id === Number(input.dataset.planDone)); if (item) { item.done = input.checked; localStorage.setItem('revisie-planner-items', JSON.stringify(items)); openPlanner(); } })); backdrop.querySelectorAll('[data-edit-plan]').forEach((button) => button.addEventListener('click', () => editPlan(Number(button.dataset.editPlan)))); backdrop.querySelectorAll('[data-delete-plan]').forEach((button) => button.addEventListener('click', () => { if (confirm('Delete this study session?')) { localStorage.setItem('revisie-planner-items', JSON.stringify(items.filter((item) => item.id !== Number(button.dataset.deletePlan)))); openPlanner(); } })); }
function editPlan(id = null) { const items = plannerItems(); const existing = items.find((item) => item.id === id); const backdrop = openModal(existing ? 'Edit study session' : 'Add study session', `<form class="notes-form"><input id="planTitle" class="note-title" required placeholder="Session title" value="${existing?.title || ''}"><select id="planSubject" class="note-subject">${Object.entries(subjectData).map(([key, subject]) => `<option value="${key}" ${key === (existing?.subject || currentSubject) ? 'selected' : ''}>${subject.label}</option>`).join('')}</select><input id="planDate" class="note-title" type="date" value="${existing?.date || new Date().toISOString().slice(0, 10)}"><input id="planMinutes" class="note-title" type="number" min="5" max="300" step="5" value="${existing?.minutes || 25}"><button class="primary-button" type="submit">Save session ${icon('check')}</button></form>`); backdrop.querySelector('form').addEventListener('submit', (event) => { event.preventDefault(); const item = { id: existing?.id || Date.now(), title: backdrop.querySelector('#planTitle').value.trim(), subject: backdrop.querySelector('#planSubject').value, date: backdrop.querySelector('#planDate').value, minutes: Number(backdrop.querySelector('#planMinutes').value) || 25, done: existing?.done || false }; const index = items.findIndex((entry) => entry.id === item.id); if (index >= 0) items[index] = item; else items.push(item); localStorage.setItem('revisie-planner-items', JSON.stringify(items)); openPlanner(); }); }
function streakState() { return JSON.parse(localStorage.getItem('revisie-streak') || '{"current":0,"lastDate":""}'); }
function markStudyComplete() { if (!revisieAccount) return; const today = new Date().toISOString().slice(0, 10); const state = streakState(); if (state.lastDate === today) return; const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10); state.current = state.lastDate === yesterday ? state.current + 1 : 1; state.lastDate = today; localStorage.setItem('revisie-streak', JSON.stringify(state)); }
function openStreak() { if (!revisieAccount) { location.href = 'account.html'; return; } const state = streakState(); const current = state.current || 0; openModal(`Your ${current} day streak`, `<div class="streak-modal-summary"><div class="streak-big">${current}</div><div><strong>consecutive study days</strong><small>Complete a review each day to keep it alive</small></div></div><div class="week-dots">${['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((day) => `<div class="week-day">${day}<i>•</i></div>`).join('')}</div><div class="milestone"><strong>Next milestone: ${Math.max(3, current + 3)} days</strong><br>Only completed study sessions count. No XP, pressure, or fake progress.</div>`); }
function setupSettingsPage() { if (!location.pathname.endsWith('settings.html')) return; const settings = JSON.parse(localStorage.getItem('revisie-settings') || '{}'); const name = document.getElementById('displayName'); const subject = document.getElementById('defaultSubject'); const minutes = document.getElementById('dailyMinutes'); const motion = document.getElementById('reduceMotion'); if (!name) return; name.value = settings.name || 'Sean'; subject.value = settings.subject || 'mathematics'; minutes.value = settings.minutes || 35; motion.checked = Boolean(settings.reduceMotion); document.getElementById('settingsForm').addEventListener('submit', (event) => { event.preventDefault(); localStorage.setItem('revisie-settings', JSON.stringify({ name: name.value.trim() || 'Sean', subject: subject.value, minutes: Number(minutes.value) || 35, reduceMotion: motion.checked })); document.documentElement.classList.toggle('reduce-motion', motion.checked); notify('Settings saved.'); }); document.getElementById('resetData').addEventListener('click', () => { if (!confirm('Reset your personal subjects, flashcards, notes, resources, and planner data?')) return; ['revisie-subjects', 'revisie-flashcards', 'revisie-note-library', 'revisie-notes', 'revisie-note-title', 'revisie-resources', 'revisie-plan'].forEach((key) => localStorage.removeItem(key)); notify('Personal data reset. Built-in GCSE content is unchanged.'); }); if (settings.reduceMotion) document.documentElement.classList.add('reduce-motion'); }
function assistantResponse(input) { const value = input.value.trim(); if (!value) return; const lower = value.toLowerCase(); const subject = subjectData[currentSubject] || subjectData.mathematics; const notes = noteLibrary.filter((note) => note.subject === currentSubject).map((note) => note.body).join(' '); const deck = getDeck(currentSubject, getUnits(currentSubject)[0].name); let answer = `For ${subject.label}, start with the key definition, then apply it to an unfamiliar example. Your current focus is ${subject.topic}.`; if (lower.includes('quiz') || lower.includes('test')) { const card = deck[Math.floor(Math.random() * deck.length)]; answer = `Quick quiz: ${card[0]} Take a moment to answer from memory, then open the matching ${getUnits(currentSubject)[0].name} deck to check it.`; } else if (lower.includes('summar')) answer = notes ? `Here is the beginning of your saved ${subject.label} note: ${notes.slice(0, 260)}${notes.length > 260 ? '...' : ''}` : `You do not have a saved ${subject.label} note yet. Add one from the Notes page and I can use it here.`; else if (lower.includes('explain') || lower.includes('help')) { const card = deck[0]; answer = `${card[0]} Answer: ${card[1]} Next, try explaining that answer without looking.`; } const panel = document.querySelector('.assistant-panel'); if (panel) { panel.querySelector('.assistant-answer')?.remove(); panel.insertAdjacentHTML('beforeend', `<div class="assistant-answer"><strong>${subject.label} study assistant</strong><br>${answer}</div>`); } input.value = ''; }
function addSubject() { const backdrop = openModal('Add a subject', `<form class="notes-form"><input id="newSubject" class="note-title" required placeholder="Subject name"><input id="newTopic" class="note-title" placeholder="First topic (optional)"><button class="primary-button" type="submit">Add subject ${icon('plus')}</button></form>`); backdrop.querySelector('form').addEventListener('submit', (event) => { event.preventDefault(); const name = backdrop.querySelector('#newSubject').value.trim(); const topic = backdrop.querySelector('#newTopic').value.trim() || 'First topic'; if (!name) return; customSubjects.push({ name, topic }); localStorage.setItem('revisie-subjects', JSON.stringify(customSubjects)); closeModal(); notify(`${name} added to your library.`); setTimeout(() => location.reload(), 350); }); }
function setupCustomSubjects() { if (!location.pathname.endsWith('subjects.html')) return; const intro = document.querySelector('.page-intro'); const grid = document.querySelector('.subject-grid'); if (!intro || !grid) return; if (!document.getElementById('addSubject')) { const button = document.createElement('button'); button.id = 'addSubject'; button.className = 'primary-button'; button.innerHTML = `Add subject ${icon('plus')}`; intro.appendChild(button); button.addEventListener('click', addSubject); } const entries = Object.entries(subjectData).filter(([key]) => key !== 'psychology'); const builtInCards = entries.map(([key, subject]) => { const route = ['mathematics', 'biology', 'history', 'psychology'].includes(key) ? `${key}.html` : `subject.html?name=${encodeURIComponent(subject.label)}`; return `<a class="subject-card" data-subject-card="${key}" data-category="${subject.category}" href="${route}"><div class="subject-top"><div class="subject-icon ${subject.color}">${icon(subject.icon)}</div><span class="progress-ring">HIGHER</span></div><strong>${subject.label}</strong><small>GCSE Higher · ${subject.board}</small><div class="bar"><span style="width:${key === 'biology' ? 72 : key === 'mathematics' ? 68 : 18}%"></span></div></a>`; }).join(''); const customCards = customSubjects.filter((subject) => !subjectData[subject.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')]).map((subject) => { const key = subject.name.toLowerCase().replace(/[^a-z0-9]+/g, '-'); return `<a class="subject-card" data-subject-card="${key}" data-category="custom" href="subject.html?name=${encodeURIComponent(subject.name)}"><div class="subject-top"><div class="subject-icon blue">${icon('book-open')}</div><span class="progress-ring">HIGHER</span></div><strong>${subject.name}</strong><small>GCSE Higher · ${subject.topic}</small><div class="bar"><span style="width:8%"></span></div></a>`; }).join(''); grid.innerHTML = builtInCards + customCards; }
function editSubject(subjectIndex) { const subject = customSubjects[subjectIndex]; if (!subject) return; const backdrop = openModal('Edit subject', `<form class="notes-form"><input id="editSubjectName" class="note-title" required value="${subject.name}"><input id="editSubjectTopic" class="note-title" value="${subject.topic}"><button class="primary-button" type="submit">Save changes ${icon('check')}</button></form>`); backdrop.querySelector('form').addEventListener('submit', (event) => { event.preventDefault(); customSubjects[subjectIndex] = { name: backdrop.querySelector('#editSubjectName').value.trim(), topic: backdrop.querySelector('#editSubjectTopic').value.trim() || 'First topic' }; localStorage.setItem('revisie-subjects', JSON.stringify(customSubjects)); closeModal(); location.reload(); }); }
