function setupCustomSubjectActions() { if (!location.pathname.endsWith('subjects.html')) return; customSubjects.forEach((subject, index) => { const key = subject.name.toLowerCase().replace(/[^a-z0-9]+/g, '-'); const card = document.querySelector(`a[data-subject-card="${key}"][data-category="custom"]`); if (!card || card.parentElement.classList.contains('custom-subject-wrap')) return; const wrap = document.createElement('div'); wrap.className = 'custom-subject-wrap'; card.replaceWith(wrap); wrap.appendChild(card); wrap.insertAdjacentHTML('beforeend', `<div class="custom-subject-actions"><button data-edit-subject="${index}" aria-label="Edit ${subject.name}">${icon('pencil')}</button><button data-delete-subject="${index}" aria-label="Delete ${subject.name}">${icon('trash-2')}</button></div>`); }); document.querySelectorAll('[data-edit-subject]').forEach((button) => button.addEventListener('click', () => editSubject(Number(button.dataset.editSubject)))); document.querySelectorAll('[data-delete-subject]').forEach((button) => button.addEventListener('click', () => deleteSubject(Number(button.dataset.deleteSubject)))); }
function setupSubjectFilters() { const filters = document.querySelector('.subject-filter'); if (!filters) return; const hasPersonalSubjects = customSubjects.some((subject) => !subjectData[subject.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')]); filters.innerHTML = `<button class="active" data-filter="all" aria-pressed="true">All subjects</button><button data-filter="core" aria-pressed="false">Core</button><button data-filter="science" aria-pressed="false">Science</button><button data-filter="language" aria-pressed="false">Languages</button><button data-filter="option" aria-pressed="false">Options</button>${hasPersonalSubjects ? '<button data-filter="custom" aria-pressed="false">Personal</button>' : ''}`; }
function setupFlashcardLibrary() { if (!location.pathname.endsWith('flashcards.html')) return; const intro = document.querySelector('.page-intro'); const grid = document.querySelector('.subject-grid'); if (!intro || !grid) return; if (!document.getElementById('addFlashcard')) { const button = document.createElement('button'); button.id = 'addFlashcard'; button.className = 'primary-button'; button.innerHTML = `Make a flashcard ${icon('plus')}`; intro.appendChild(button); button.addEventListener('click', addFlashcard); } grid.innerHTML = Object.entries(subjectData).filter(([key]) => key !== 'psychology').flatMap(([key, subject]) => getUnits(key).map((unit) => `<button class="subject-card" data-action="unit-review" data-subject="${key}" data-unit="${unit.name}"><div class="subject-top"><div class="subject-icon ${subject.color}">${icon(subject.icon)}</div><span class="progress-ring">${getDeck(key, unit.name).length} CARDS</span></div><strong>${subject.label}</strong><small>GCSE Higher · ${unit.name}</small><div class="bar"><span style="width:18%"></span></div></button>`)).join(''); }
function setupSubjectUnits() { if (location.pathname.endsWith('subjects.html') || location.pathname.endsWith('flashcards.html') || location.pathname.endsWith('index.html')) return; const grid = document.querySelector('.subject-grid'); const intro = document.querySelector('.page-intro'); const subject = subjectData[currentSubject]; if (!grid || !subject) return; if (intro && !document.getElementById('subjectAddCard')) { intro.insertAdjacentHTML('beforeend', `<div class="subject-actions"><button class="primary-button" id="subjectAddCard">Make a flashcard ${icon('plus')}</button><button class="secondary-button" id="subjectManageCards">Manage flashcards ${icon('settings-2')}</button><button class="secondary-button" id="subjectAddTopic">Add topic ${icon('plus')}</button></div>`); intro.querySelector('#subjectAddCard').addEventListener('click', () => addFlashcardFor(currentSubject, getUnits(currentSubject)[0].name)); intro.querySelector('#subjectManageCards').addEventListener('click', () => openCardManager(currentSubject, getUnits(currentSubject)[0].name)); intro.querySelector('#subjectAddTopic').addEventListener('click', () => addTopic(currentSubject)); } grid.innerHTML = getUnits(currentSubject).map((unit, index) => `<div class="topic-card-wrap"><button class="subject-card" data-action="unit-review" data-subject="${currentSubject}" data-unit="${unit.name}"><div class="subject-top"><div class="subject-icon ${subject.color || 'blue'}">${icon(subject.icon || 'book-open')}</div><span class="progress-ring">${getDeck(currentSubject, unit.name).length} CARDS</span></div><strong>${unit.name}</strong><small>GCSE Higher · active recall deck</small><div class="bar"><span style="width:18%"></span></div></button>${unit.custom ? `<div class="topic-actions"><button type="button" data-edit-topic="${index - (getUnits(currentSubject).length - (customTopics[currentSubject] || []).length)}" aria-label="Edit ${unit.name}">${icon('pencil')}</button><button type="button" data-delete-topic="${index - (getUnits(currentSubject).length - (customTopics[currentSubject] || []).length)}" aria-label="Delete ${unit.name}">${icon('trash-2')}</button></div>` : ''}</div>`).join(''); grid.querySelectorAll('[data-edit-topic]').forEach((button) => button.addEventListener('click', (event) => { event.preventDefault(); event.stopPropagation(); editTopic(currentSubject, Number(button.dataset.editTopic)); })); grid.querySelectorAll('[data-delete-topic]').forEach((button) => button.addEventListener('click', (event) => { event.preventDefault(); event.stopPropagation(); deleteTopic(currentSubject, Number(button.dataset.deleteTopic)); })); }
function addTopic(subjectKey) { const subject = subjectData[subjectKey]; const backdrop = openModal(`Add ${subject.label} topic`, `<form class="notes-form"><input id="topicName" class="note-title" required placeholder="Topic or unit name"><button class="primary-button" type="submit">Add topic ${icon('plus')}</button></form>`); backdrop.querySelector('form').addEventListener('submit', (event) => { event.preventDefault(); const name = backdrop.querySelector('#topicName').value.trim(); if (!name) return; customTopics[subjectKey] = customTopics[subjectKey] || []; if (getUnits(subjectKey).some((unit) => unit.name.toLowerCase() === name.toLowerCase())) { notify('That topic already exists.'); return; } customTopics[subjectKey].push({ name }); localStorage.setItem('revisie-topics', JSON.stringify(customTopics)); closeModal(); setupSubjectUnits(); notify('Topic added with three starter flashcards.'); }); }
