function enhanceSubjectFilters() { const filters = document.querySelector('.subject-filter'); if (!filters) return; const cards = [...document.querySelectorAll('[data-subject-card]')]; if (!cards.length) return; const status = document.createElement('p'); status.className = 'subject-filter-status'; status.hidden = true; status.setAttribute('aria-live', 'polite'); status.textContent = 'No subjects in this group yet.'; filters.after(status); filters.querySelectorAll('button').forEach((button) => button.addEventListener('click', () => { const selected = button.dataset.filter; let visible = 0; filters.querySelectorAll('button').forEach((item) => { const active = item === button; item.classList.toggle('active', active); item.setAttribute('aria-pressed', String(active)); }); cards.forEach((card) => { const show = selected === 'all' || card.dataset.category === selected; card.hidden = !show; if (show) visible += 1; }); status.hidden = visible > 0; })); }
