function subjectProgress() { return JSON.parse(localStorage.getItem('revisie-subject-progress') || '{}'); }
function topicProgress() { return JSON.parse(localStorage.getItem('revisie-topic-progress') || '{}'); }
function topicProgressKey(subjectKey, unitName) { return `${subjectKey}::${unitName}`; }
function topicProgressPercent(subjectKey, unitName) { const total = getDeck(subjectKey, unitName).length; const complete = Number(topicProgress()[topicProgressKey(subjectKey, unitName)] || 0); return total ? Math.round(Math.min(complete, total) / total * 100) : 0; }
function markTopicCardKnown(subjectKey, unitName, deckSize) { const progress = topicProgress(); const key = topicProgressKey(subjectKey, unitName); progress[key] = Math.min(deckSize || getDeck(subjectKey, unitName).length, Number(progress[key] || 0) + 1); localStorage.setItem('revisie-topic-progress', JSON.stringify(progress)); }
function subjectCardTotal(subjectKey) { return subjectData[subjectKey] ? getUnits(subjectKey).reduce((total, unit) => total + getDeck(subjectKey, unit.name).length, 0) : 1; }
function subjectProgressPercent(subjectKey) { const total = subjectCardTotal(subjectKey); return total ? Math.round(Math.min(Number(subjectProgress()[subjectKey] || 0), total) / total * 100) : 0; }
function markCardKnown(subjectKey, deckSize) { const progress = subjectProgress(); const total = Math.max(subjectCardTotal(subjectKey), deckSize || 1); progress[subjectKey] = Math.min(total, Number(progress[subjectKey] || 0) + 1); localStorage.setItem('revisie-subject-progress', JSON.stringify(progress)); }
function renderSubjectProgress() { document.querySelectorAll('[data-subject-card]').forEach((card) => { const percent = subjectProgressPercent(card.dataset.subjectCard); const meter = card.querySelector('.bar span'); const label = card.querySelector('.progress-ring'); if (meter) meter.style.width = `${percent}%`; if (label) label.textContent = `${percent}%`; card.setAttribute('aria-label', `${card.querySelector('strong')?.textContent || 'Subject'}: ${percent}% of cards marked known`); }); }
function renderTopicProgress() { document.querySelectorAll('[data-action="unit-review"]').forEach((card) => { const percent = topicProgressPercent(card.dataset.subject, card.dataset.unit); const meter = card.querySelector('.bar span'); const label = card.querySelector('.progress-ring'); if (meter) meter.style.width = `${percent}%`; if (label) label.textContent = `${percent}%`; card.setAttribute('aria-label', `${card.dataset.unit}: ${percent}% of flashcards marked known`); }); }
function reviewCards(cards, title) {
  const subjectKey = Object.entries(subjectData).find(([, subject]) => title.startsWith(`${subject.label} /`))?.[0] || currentSubject;
  const unitName = title.split(' / ').slice(1).join(' / ');
  const queue = uniqueCards(cards);
  const total = queue.length;
  let known = 0;
  const render = () => {
    if (!queue.length) {
      openModal(title, `<div class="flashcard-meta"><span>${known} of ${total} cards complete</span><span>Session complete</span></div><div class="flashcard answer"><div><p>Great work.</p><small>All cards marked known</small></div></div>`);
      renderSubjectProgress(); renderTopicProgress();
      return;
    }
    const card = queue[0];
    const backdrop = openModal(title, `<div class="flashcard-meta"><span>${known} complete · ${queue.length} remaining</span><span>Click to reveal</span></div><button class="flashcard" id="flashcard"><div><p>${card[0]}</p><small>Question</small></div></button><div class="review-actions"><button class="again" id="again">Review again</button><button class="known" id="known">I knew this</button></div>`);
    const flashcard = backdrop.querySelector('#flashcard');
    flashcard.addEventListener('click', () => { const answer = flashcard.classList.toggle('answer'); flashcard.querySelector('p').textContent = answer ? card[1] : card[0]; flashcard.querySelector('small').textContent = answer ? 'Answer' : 'Question'; });
    backdrop.querySelector('#again').addEventListener('click', () => { markStudyComplete(); queue.push(queue.shift()); notify('Card moved to the end of your queue.'); render(); });
    backdrop.querySelector('#known').addEventListener('click', () => { markStudyComplete(); markCardKnown(subjectKey, total); if (getUnits(subjectKey).some((unit) => unit.name === unitName)) markTopicCardKnown(subjectKey, unitName, total); updateNavigationCounts(); queue.shift(); known += 1; notify('Card marked as known. Nice work.'); render(); });
  };
  render();
}
