function setupAccountRoute() { if (!location.pathname.endsWith('account.html')) return; const form = document.getElementById('accountForm'); const account = JSON.parse(localStorage.getItem('revisie-account') || 'null'); if (!form) return; if (account) { document.getElementById('accountName').value = account.name || ''; document.getElementById('accountEmail').value = account.email || ''; } form.addEventListener('submit', async (event) => { event.preventDefault(); const name = document.getElementById('accountName').value.trim(); const email = document.getElementById('accountEmail').value.trim(); const password = document.getElementById('accountPassword').value; const button = form.querySelector('button'); button.disabled = true; button.textContent = 'Signing in…'; try { const client = await getSupabaseClient(); let { data, error } = await client.auth.signInWithPassword({ email, password }); if (error && /Invalid login credentials/i.test(error.message)) { const result = await client.auth.signUp({ email, password, options: { emailRedirectTo: `${location.origin}/account.html`, data: { display_name: name || email.split('@')[0] } } }); data = result.data; error = result.error; if (!error && !data.session) { notify('Account created. Check your email to confirm it, then sign in.'); return; } } if (error) throw error; const displayName = data.user?.user_metadata?.display_name || name || email.split('@')[0]; localStorage.setItem('revisie-account', JSON.stringify({ id: data.user.id, name: displayName, email })); await restoreWorkspace(); location.href = 'index.html'; } catch (error) { notify(error.message || 'Could not sign in.'); } finally { button.disabled = false; button.innerHTML = `Sign in or create account ${icon('arrow-right')}`; lucide.createIcons(); } }); }
